public sealed partial class ProxyHandlers
{
    /// <summary>
    /// Handles the Connect proxy, which authenticates a connection and returns its initial state: the user,
    /// connection info, server-side subscriptions and the like.
    /// </summary>
    /// <remarks>The function returns a result, or throws ProxyErrorException to answer with an error or ProxyDisconnectException to close the connection.</remarks>
    /// <param name="handle">Decides the answer: called with the request and its context.</param>
    /// <returns>The handler, to serve with the framework's adapter.</returns>
    public CentHandler Connect(Func<ConnectRequest, HandlerContext, Task<ConnectResult>> handle) =>
        Create("connect", Answers.All, handle, Wire.Info<ConnectRequest>(), Wire.Info<ConnectResult>());

    /// <summary>
    /// Handles the Refresh proxy, which is called when a connection is about to expire, to decide whether
    /// it may live on, and until when.
    /// </summary>
    /// <remarks>The function returns a result: this proxy cannot answer with an error or a disconnect.</remarks>
    /// <param name="handle">Decides the answer: called with the request and its context.</param>
    /// <returns>The handler, to serve with the framework's adapter.</returns>
    public CentHandler Refresh(Func<RefreshRequest, HandlerContext, Task<RefreshResult>> handle) =>
        Create("refresh", Answers.ResultOnly, handle, Wire.Info<RefreshRequest>(), Wire.Info<RefreshResult>());

    /// <summary>
    /// Handles the Subscribe proxy, which decides whether a client may subscribe to a channel.
    /// </summary>
    /// <remarks>The function returns a result, or throws ProxyErrorException to answer with an error or ProxyDisconnectException to close the connection.</remarks>
    /// <param name="handle">Decides the answer: called with the request and its context.</param>
    /// <returns>The handler, to serve with the framework's adapter.</returns>
    public CentHandler Subscribe(Func<SubscribeRequest, HandlerContext, Task<SubscribeResult>> handle) =>
        Create("subscribe", Answers.All, handle, Wire.Info<SubscribeRequest>(), Wire.Info<SubscribeResult>());

    /// <summary>
    /// Handles the Publish proxy, which decides whether a client may publish into a channel, and may
    /// change the publication.
    /// </summary>
    /// <remarks>The function returns a result, or throws ProxyErrorException to answer with an error or ProxyDisconnectException to close the connection.</remarks>
    /// <param name="handle">Decides the answer: called with the request and its context.</param>
    /// <returns>The handler, to serve with the framework's adapter.</returns>
    public CentHandler Publish(Func<PublishRequest, HandlerContext, Task<PublishResult>> handle) =>
        Create("publish", Answers.All, handle, Wire.Info<PublishRequest>(), Wire.Info<PublishResult>());

    /// <summary>
    /// Handles the RPC proxy, which handles a custom call a client makes over its real-time connection.
