        Create("sub_refresh", Answers.ResultOnly, handle, Wire.Info<SubRefreshRequest>(), Wire.Info<SubRefreshResult>());

    /// <summary>
    /// Handles the NotifyCacheEmpty proxy, which tells the backend that a client subscribed to a channel in
    /// cache recovery mode which has no publication to recover from, so that the
